function compute(s) {
  const nq = Math.max(1, Math.round(s.nq));
  const nk = Math.max(1, Math.round(s.nk));
  const dk = Math.max(1, Math.round(s.dk));
  const dv = Math.max(1, Math.round(s.dv));
  const scale = !!s.scale;

  // Build Q, K, V with safe dimensions
  const Q = [], K = [], V = [];
  for (let i = 0; i < nq; i++) {
    const row = [];
    for (let j = 0; j < dk; j++) {
      const v = (s.Q && s.Q[i] && s.Q[i][j] !== undefined) ? Number(s.Q[i][j]) : 0;
      row.push(Number.isFinite(v) ? v : 0);
    }
    Q.push(row);
  }
  for (let i = 0; i < nk; i++) {
    const row = [];
    for (let j = 0; j < dk; j++) {
      const v = (s.K && s.K[i] && s.K[i][j] !== undefined) ? Number(s.K[i][j]) : 0;
      row.push(Number.isFinite(v) ? v : 0);
    }
    K.push(row);
  }
  for (let i = 0; i < nk; i++) {
    const row = [];
    for (let j = 0; j < dv; j++) {
      const v = (s.V && s.V[i] && s.V[i][j] !== undefined) ? Number(s.V[i][j]) : 0;
      row.push(Number.isFinite(v) ? v : 0);
    }
    V.push(row);
  }

  // S = Q K^T
  const S = [];
  for (let i = 0; i < nq; i++) {
    const row = [];
    for (let j = 0; j < nk; j++) {
      let acc = 0;
      for (let t = 0; t < dk; t++) acc += Q[i][t] * K[j][t];
      row.push(acc);
    }
    S.push(row);
  }

  const denom = Math.sqrt(dk);
  const Sscaled = S.map(row => row.map(x => x / denom));

  // softmax row-wise on Sscaled (or S if scale off)
  const src = scale ? Sscaled : S;
  const A = [];
  for (let i = 0; i < nq; i++) {
    const row = src[i];
    let m = -Infinity;
    for (let j = 0; j < nk; j++) if (row[j] > m) m = row[j];
    if (!Number.isFinite(m)) m = 0;
    const ex = row.map(x => Math.exp(x - m));
    let sum = 0;
    for (let j = 0; j < nk; j++) sum += ex[j];
    if (!(sum > 0) || !Number.isFinite(sum)) {
      A.push(row.map(() => 1 / nk));
    } else {
      A.push(ex.map(x => x / sum));
    }
  }

  // O = A V
  const O = [];
  for (let i = 0; i < nq; i++) {
    const row = [];
    for (let j = 0; j < dv; j++) {
      let acc = 0;
      for (let t = 0; t < nk; t++) acc += A[i][t] * V[t][j];
      row.push(acc);
    }
    O.push(row);
  }

  const rowSums = A.map(row => row.reduce((a, b) => a + b, 0));

  // selected row
  let row = Math.round(s.row);
  if (!Number.isFinite(row)) row = 0;
  row = Math.max(0, Math.min(nq - 1, row));

  // explicit weighted sum for selected row
  const weighted = [];
  for (let j = 0; j < dv; j++) {
    let acc = 0;
    for (let t = 0; t < nk; t++) acc += A[row][t] * V[t][j];
    weighted.push(acc);
  }

  return {
    nq, nk, dk, dv,
    scale: scale ? 1 : 0,
    Q, K, V,
    S, Sscaled, A, O,
    rowSums,
    row,
    weightsRow: A[row],
    weightedRow: weighted,
    outputRow: O[row],
    sqrtDk: denom
  };
}

function render(s, r) {
  const W = 760, H = 560;
  const parts = [];
  const pad = 16;

  // Layout: three heatmaps in a row
  const hmW = 200, hmH = 170;
  const y0 = 60;
  const x1 = pad + 10;
  const x2 = x1 + hmW + 60;
  const x3 = x2 + hmW + 60;

  const nq = r.nq, nk = r.nk, dv = r.dv;

  const rowLabelsQ = [];
  for (let i = 0; i < nq; i++) rowLabelsQ.push('q' + (i + 1));
  const colLabelsK = [];
  for (let j = 0; j < nk; j++) colLabelsK.push('k' + (j + 1));
  const colLabelsV = [];
  for (let j = 0; j < dv; j++) colLabelsV.push('d' + (j + 1));

  // Title
  parts.push(L.text(W / 2, 24, 'Scaled Dot-Product Attention', { size: 18, anchor: 'middle', weight: 'bold' }));
  parts.push(L.text(W / 2, 44, r.scale ? 'scores divided by sqrt(d_k) = ' + L.fmt(r.sqrtDk, 3) : 'scaling OFF (raw dot products)', { size: 13, anchor: 'middle', color: '#555' }));

  // Heatmap 1: scores
  const scoreMatrix = r.scale ? r.Sscaled : r.S;
  const scoreTitle = r.scale ? 'Scores  S / sqrt(d_k)' : 'Scores  S = Q K^T';
  parts.push(L.heatmap({
    x: x1, y: y0, w: hmW, h: hmH,
    matrix: scoreMatrix,
    rowLabels: rowLabelsQ,
    colLabels: colLabelsK,
    title: scoreTitle,
    fmt: (v) => L.fmt(v, 2),
    highlight: [[r.row, 0]]
  }));

  // Heatmap 2: weights
  parts.push(L.heatmap({
    x: x2, y: y0, w: hmW, h: hmH,
    matrix: r.A,
    rowLabels: rowLabelsQ,
    colLabels: colLabelsK,
    title: 'Weights  A = softmax(...)',
    min: 0, max: 1,
    fmt: (v) => L.fmt(v, 2),
    highlight: [[r.row, 0]]
  }));

  // Heatmap 3: output
  parts.push(L.heatmap({
    x: x3, y: y0, w: hmW, h: hmH,
    matrix: r.O,
    rowLabels: rowLabelsQ,
    colLabels: colLabelsV,
    title: 'Output  O = A V',
    fmt: (v) => L.fmt(v, 2),
    highlight: [[r.row, 0]]
  }));

  // Row sums annotation
  const rsY = y0 + hmH + 22;
  parts.push(L.text(x2, rsY, 'row sums of A:', { size: 12, anchor: 'start', color: '#333' }));
  for (let i = 0; i < nq; i++) {
    parts.push(L.text(x2 + 90 + i * 55, rsY, L.fmt(r.rowSums[i], 3), { size: 12, anchor: 'start', color: '#333' }));
  }

  // Bar chart of selected row weights
  const barY = rsY + 30;
  parts.push(L.bars({
    x: pad + 10, y: barY, w: 340, h: 150,
    values: r.weightsRow,
    labels: colLabelsK,
    title: 'Weights for query row ' + (r.row + 1),
    yLabel: 'weight',
    min: 0, max: 1,
    fmt: (v) => L.fmt(v, 3)
  }));

  // Weighted sum text
  const tx = pad + 380;
  parts.push(L.text(tx, barY + 10, 'Weighted sum of V rows for query ' + (r.row + 1) + ':', { size: 13, anchor: 'start', weight: 'bold' }));
  for (let j = 0; j < dv; j++) {
    parts.push(L.text(tx, barY + 34 + j * 20, 'dim ' + (j + 1) + ': ' + L.fmt(r.weightedRow[j], 3), { size: 12, anchor: 'start' }));
  }
  parts.push(L.text(tx, barY + 34 + dv * 20 + 10, 'Output row ' + (r.row + 1) + ':', { size: 13, anchor: 'start', weight: 'bold' }));
  for (let j = 0; j < dv; j++) {
    parts.push(L.text(tx, barY + 34 + dv * 20 + 34 + j * 20, 'dim ' + (j + 1) + ': ' + L.fmt(r.outputRow[j], 3), { size: 12, anchor: 'start' }));
  }

  return L.svg(W, H, parts.join(''));
}

function show(s, r) {
  const out = [];
  out.push({ label: 'n_q', value: r.nq, digits: 0, note: 'number of queries' });
  out.push({ label: 'n_k', value: r.nk, digits: 0, note: 'number of keys/values' });
  out.push({ label: 'd_k', value: r.dk, digits: 0, note: 'key dimension' });
  out.push({ label: 'd_v', value: r.dv, digits: 0, note: 'value dimension' });
  out.push({ label: 'sqrt(d_k)', value: r.sqrtDk, digits: 3, note: 'scaling denominator' });
  out.push({ label: 'scaling', value: r.scale ? 'on' : 'off', digits: 0, note: 'divide scores by sqrt(d_k)' });
  out.push({ label: 'S = Q K^T', value: r.S, digits: 3, note: 'raw scores', rowLabels: r.Q.map((_, i) => 'q' + (i + 1)), colLabels: r.K.map((_, j) => 'k' + (j + 1)) });
  out.push({ label: 'S / sqrt(d_k)', value: r.Sscaled, digits: 3, note: 'scaled scores', rowLabels: r.Q.map((_, i) => 'q' + (i + 1)), colLabels: r.K.map((_, j) => 'k' + (j + 1)) });
  out.push({ label: 'A = softmax(...)', value: r.A, digits: 3, note: 'attention weights', rowLabels: r.Q.map((_, i) => 'q' + (i + 1)), colLabels: r.K.map((_, j) => 'k' + (j + 1)) });
  out.push({ label: 'row sums of A', value: r.rowSums, digits: 3, note: 'each should be 1', colLabels: r.Q.map((_, i) => 'q' + (i + 1)) });
  out.push({ label: 'O = A V', value: r.O, digits: 3, note: 'output', rowLabels: r.Q.map((_, i) => 'q' + (i + 1)), colLabels: r.V[0].map((_, j) => 'd' + (j + 1)) });
  out.push({ label: 'weights row ' + (r.row + 1), value: r.weightsRow, digits: 3, note: 'selected query weights', colLabels: r.K.map((_, j) => 'k' + (j + 1)) });
  out.push({ label: 'weighted V row ' + (r.row + 1), value: r.weightedRow, digits: 3, note: 'sum_j A[row][j] V[j]', colLabels: r.V[0].map((_, j) => 'd' + (j + 1)) });
  return out;
}

function checks(s, r) {
  const out = [];

  // 1. Row sums of A equal 1
  let maxDev = 0;
  for (let i = 0; i < r.nq; i++) {
    maxDev = Math.max(maxDev, Math.abs(r.rowSums[i] - 1));
  }
  out.push({
    name: 'each row of A sums to 1',
    pass: maxDev < 1e-9,
    detail: 'max |rowSum - 1| = ' + L.fmt(maxDev, 3)
  });

  // 2. Weights non-negative
  let minW = Infinity;
  for (let i = 0; i < r.nq; i++) {
    for (let j = 0; j < r.nk; j++) minW = Math.min(minW, r.A[i][j]);
  }
  out.push({
    name: 'all attention weights >= 0',
    pass: minW >= -1e-12,
    detail: 'min weight = ' + L.fmt(minW, 3)
  });

  // 3. O equals A V recomputed
  let maxO = 0;
  for (let i = 0; i < r.nq; i++) {
    for (let j = 0; j < r.dv; j++) {
      let acc = 0;
      for (let t = 0; t < r.nk; t++) acc += r.A[i][t] * r.V[t][j];
      maxO = Math.max(maxO, Math.abs(acc - r.O[i][j]));
    }
  }
  out.push({
    name: 'O equals A V',
    pass: maxO < 1e-9,
    detail: 'max |O - A V| = ' + L.fmt(maxO, 3)
  });

  // 4. Scaling divides scores by sqrt(d_k)
  let maxS = 0;
  for (let i = 0; i < r.nq; i++) {
    for (let j = 0; j < r.nk; j++) {
      maxS = Math.max(maxS, Math.abs(r.Sscaled[i][j] - r.S[i][j] / r.sqrtDk));
    }
  }
  out.push({
    name: 'Sscaled = S / sqrt(d_k)',
    pass: maxS < 1e-9,
    detail: 'max deviation = ' + L.fmt(maxS, 3)
  });

  // 5. Selected row weighted sum matches output row
  let maxW = 0;
  for (let j = 0; j < r.dv; j++) {
    maxW = Math.max(maxW, Math.abs(r.weightedRow[j] - r.outputRow[j]));
  }
  out.push({
    name: 'selected row: weighted V equals output row',
    pass: maxW < 1e-9,
    detail: 'max deviation = ' + L.fmt(maxW, 3)
  });

  return out;
}
